<script setup>
import {RouterLink} from "vue-router";
import TablePanel from '../../shared/components/TablePanel.vue';

import { computed,ref } from 'vue';
import FinancePagination from '../finance/FinancePagination.vue';
import DigitalCategoryDetails from './DigitalCategoryDetails.vue';
import { connectionPayload,providerNames,money,time,credentialAfterIdentityChange,catalogProductChoices } from './digital-model.js';
const props=defineProps({vm:{type:Object,required:true},canSetup:Boolean,canAssign:Boolean});
const draft=ref(null),credential=ref(''),catalog=ref([]),products=ref([]),assignment=ref(null),setupKey=props.vm.key(),grantKey=props.vm.key();
const detailsId=ref(null);
const details=computed(()=>props.vm.state.connections.find(row=>row.id===detailsId.value));
const mains=computed(()=>props.vm.state.options.accounts.filter(row=>row.type==='main_agent'));
const connectionOwners=computed(()=>draft.value?.provider==='topup'?props.vm.state.options.accounts.filter(row=>row.type==='system'):mains.value);
const gateway=computed(()=>props.vm.state.options.gateways?.[draft.value?.provider]||props.vm.state.options.gateway);
const children=computed(()=>props.vm.state.options.accounts.filter(row=>Number(row.parent_id)===props.vm.ownId.value&&row.status==='active'));
const assignmentTargets=computed(()=>children.value.filter(row=>assignment.value?.kind==='pos'?row.type==='pos':['main_agent','sub_agent','sub_branch'].includes(row.type)));
const assignmentOffers=computed(()=>assignment.value?.connection.offers.filter(row=>assignment.value.connection.effective_offer_ids?.includes(row.id))||[]);
const grants=computed(()=>props.vm.state.connections.flatMap(row=>row.grants.filter(grant=>Number(grant.from_account_id)===props.vm.ownId.value).map(grant=>({...grant,connection:row}))));
function cleanOffer(row){return {...(row.id?{id:row.id}:{}),product_id:row.product_id,remote_id:row.remote_id||'',province_id:row.province_id||'',...(row.bein_province_id?{bein_province_id:row.bein_province_id}:{}),retail:row.retail,active:row.active};}
async function productChoices(){products.value=[];if(!draft.value?.account_id||draft.value.provider==='topup')return;try{products.value=(await props.vm.api.options(props.vm.signal,{main_account_id:draft.value.account_id})).data.products;}catch(error){props.vm.state.error=await props.vm.failure(error);}}
async function edit(row=null){credential.value='';catalog.value=[];draft.value=row?{id:row.id,version:row.version,provider:row.provider,account_id:row.account_id,provider_id:row.provider_id,active:row.active,offers:row.offers.map(cleanOffer),catalog_snapshot_id:null}:{id:null,version:0,provider:'rabiaa',account_id:'',provider_id:'',active:true,offers:[],catalog_snapshot_id:null};if(row)catalog.value=row.offers.filter(offer=>offer.remote_id).map(offer=>({key:`${offer.remote_id}:${offer.province_id||''}`,remote_id:offer.remote_id,province_id:offer.province_id||'',remote_name:offer.remote_name||offer.name,province:offer.province,retail:offer.retail}));await productChoices();}
function changeIdentity(field){credential.value=credentialAfterIdentityChange(credential.value,field);draft.value.offers=[];draft.value.catalog_snapshot_id=null;catalog.value=[];productChoices();}
function bound(row){return draft.value?.offers.find(offer=>offer.remote_id===row.remote_id&&(offer.province_id||'')===(row.province_id||''));}
function choices(row){return catalogProductChoices(products.value,draft.value.offers,bound(row)?.product_id);}
function bind(row,value){const existing=bound(row);draft.value.offers=draft.value.offers.filter(offer=>offer!==existing);if(!value)return;const previous=props.vm.state.connections.find(connection=>connection.id===draft.value.id)?.offers.find(offer=>Number(offer.product_id)===Number(value));draft.value.offers.push({...previous?.id?{id:previous.id}:{},product_id:Number(value),remote_id:row.remote_id,province_id:row.province_id||'',retail:existing?.retail||row.retail,active:existing?.active??true});}
async function save(close=true){try{const payload=connectionPayload(draft.value,credential.value),row=await props.vm.execute(payload,setupKey,(body,signal)=>props.vm.api.configure(draft.value.id,body,signal),'تم حفظ إعداد الربط.');if(!row)return null;credential.value='';draft.value={...draft.value,id:row.id,version:row.version,offers:row.offers.map(cleanOffer)};await props.vm.load();if(row.provider==='topup'){const synced=await synchronize(row);if(synced){row.version=synced.version;row.offers=synced.offers;draft.value={...draft.value,version:synced.version,offers:synced.offers.map(cleanOffer)};}}if(close){draft.value=null;if(row.provider==='topup')detailsId.value=row.id;}return row;}catch(error){props.vm.state.error=await props.vm.failure(error);return null;}}
async function loadCatalog(){if(props.vm.state.busy)return;try{if(!draft.value.id||credential.value.trim()){const prepared={...draft.value,offers:draft.value.offers.map(row=>({...row}))};prepared.catalog_snapshot_id=null;if(credential.value.trim())prepared.offers=prepared.offers.map(offer=>({...offer,remote_id:'',province_id:''}));const payload=connectionPayload(prepared,credential.value),row=await props.vm.execute(payload,setupKey,(body,signal)=>props.vm.api.configure(prepared.id,body,signal),'تم حفظ بيانات التوكن في الخادم.');if(!row)return;credential.value='';draft.value.id=row.id;draft.value.version=row.version;draft.value.offers=row.offers.map(cleanOffer);await props.vm.load();}props.vm.state.busy=true;const result=await props.vm.api.catalog(draft.value.id,draft.value.version,props.vm.signal);catalog.value=result.data.catalog;draft.value.catalog_snapshot_id=result.data.id;}catch(error){props.vm.state.error=await props.vm.failure(error);}finally{props.vm.state.busy=false;}}
async function synchronize(row,catalogOnly=false){if(props.vm.state.busy)return null;props.vm.state.busy=true;try{const result=(await props.vm.api[catalogOnly?'syncCatalog':'sync'](row.id,row.version,props.vm.signal)).data;props.vm.state.notice=[result.sync.balance==='ok'?'تم تحديث رصيد الشركة.':result.sync.balance_message,result.sync.catalog_message].filter(Boolean).join(' ');await props.vm.load();return result;}catch(error){props.vm.state.error=await props.vm.failure(error);return null;}finally{props.vm.state.busy=false;}}
async function refreshBalance(row){if(props.vm.state.busy)return;props.vm.state.busy=true;try{await props.vm.api.balance(row.id,props.vm.signal);await props.vm.load();}catch(error){props.vm.state.error=await props.vm.failure(error);}finally{props.vm.state.busy=false;}}
async function toggle(row){const payload=connectionPayload({...row,offers:row.offers.map(cleanOffer),active:!row.active});const result=await props.vm.execute(payload,setupKey,(body,signal)=>props.vm.api.configure(row.id,body,signal));if(result)await props.vm.load();}
function assign(connection){assignment.value={connection,kind:children.value.some(row=>row.type!=='pos')?'agent':'pos',target:'',offer_ids:[],active:true,version:0};}
function loadAllocation(){const grant=assignment.value.connection.grants.find(row=>Number(row.target_account_id)===Number(assignment.value.target));Object.assign(assignment.value,{version:grant?.version||0,offer_ids:[...(grant?.offer_ids||[])],active:grant?.active??true});}
async function saveGrant(){const allocation=assignment.value,payload={version:allocation.version,offer_ids:[...allocation.offer_ids],active:allocation.active};const result=await props.vm.execute(payload,grantKey,(body,signal)=>props.vm.api.grant(allocation.connection.id,Number(allocation.target),body,signal));if(result){assignment.value=null;await props.vm.load();}}
async function toggleGrant(grant){const payload={version:grant.version,offer_ids:[...grant.offer_ids],active:!grant.active};const result=await props.vm.execute(payload,grantKey,(body,signal)=>props.vm.api.grant(grant.connection_id,grant.target_account_id,body,signal));if(result)await props.vm.load();}
</script>
<template><section class="card"><div class="toolbar"><h3>{{canSetup?'ربط الشركات والوكلاء':'توزيع الفئات'}}</h3><RouterLink v-if="canSetup||canAssign" class="btn" :to="canSetup?'/topup/allocation':'/topup/distribution'">{{canSetup?'تخصيص فئات Topup':'توزيع فئات Topup'}}</RouterLink><button v-if="canSetup" class="btn primary" :disabled="vm.state.busy" @click="edit()">إضافة ربط</button></div><form v-if="draft&&canSetup" class="digital-config" @submit.prevent="save()"><h4 v-if="draft.id" class="digital-edit-title">تعديل الربط الحالي</h4><div class="digital-connection-fields"><div class="formgrid"><label>الخدمة<select v-model="draft.provider" :disabled="!!draft.id||vm.state.busy" @change="changeIdentity('provider');if(draft.provider==='topup')draft.account_id=props.vm.ownId.value"><option v-for="(name,id) in providerNames" :key="id" :value="id">{{name}}</option></select></label><label>{{draft.provider==='topup'?'إدارة رصيد التبب':'الوكيل'}}<select v-model="draft.account_id" required :disabled="!!draft.id||vm.state.busy" @change="changeIdentity('agent')"><option value="" disabled>اختر الوكيل</option><option v-for="row in connectionOwners" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>التوكن / API Key<input v-model="credential" type="password" autocomplete="off" :disabled="vm.state.busy" :placeholder="draft.id?'اتركه فارغًا للإبقاء على الحالي':''" maxlength="8000"></label><label>حالة الربط<select v-model="draft.active" :disabled="vm.state.busy"><option :value="true">مفعّل</option><option :value="false">معطّل</option></select></label></div></div><p v-if="draft.provider==='topup'" class="help">توكن آسياسيل عند مدير النظام؛ يخصص المدير الرصيد والفئات للوكلاء.</p><p v-if="gateway&&!gateway.configured" class="notice warn">الخدمة غير متصلة: {{gateway.missing.join('، ')}}.</p><div v-if="draft.provider!=='topup'" class="formfoot"><button type="button" class="btn" :disabled="vm.state.busy||!draft.account_id||!gateway?.configured" @click="loadCatalog">{{vm.state.busy?'جارٍ الجلب…':!draft.id||credential?'حفظ التوكن وجلب فئات الشركة':'جلب فئات الشركة'}}</button></div><p v-if="draft.provider!=='topup' && draft.catalog_snapshot_id && !catalog.length" class="notice warn" role="status">اتصلنا بالشركة بنجاح، لكن الشركة أعادت قائمة فئات فارغة لهذا التوكن. اطلب من المزود تفعيل الشركات والفئات لحسابك ثم اضغط جلب فئات الشركة. توفر الرصيد وحده لا يعني توفر فئات للبيع.</p><section v-if="draft.provider!=='topup' && catalog.length" class="digital-company-catalog" aria-live="polite"><h4>{{draft.catalog_snapshot_id?'فئات الشركة · جلب جديد':'الفئات المرتبطة حاليًا'}} · {{catalog.length}}</h4><div v-for="item in catalog" :key="item.key" class="digital-company-category"><div><b>{{item.remote_name}}</b><small v-if="item.province">{{item.province}}</small></div><label>الفئة في النظام<select :value="bound(item)?.product_id||''" @change="bind(item,$event.target.value)"><option value="">بدون ربط</option><option v-for="product in choices(item)" :key="product.id" :value="product.id">{{product.name}}</option></select></label><label>مبلغ البيع · د.ع<input :value="bound(item)?.retail??item.retail" inputmode="decimal" :disabled="!bound(item)||vm.state.busy" :required="!!bound(item)" @input="bound(item).retail=$event.target.value"></label></div></section><section v-if="draft.provider==='topup'&&draft.offers.length" class="digital-company-catalog"><h4>فئات الشركة المرتبطة</h4><div v-for="offer in draft.offers" :key="offer.id" class="digital-company-category"><div><b>{{vm.state.connections.find(row=>row.id===draft.id)?.offers.find(row=>row.id===offer.id)?.remote_name}}</b><small dir="ltr">{{offer.remote_id}}</small></div><label>سعر المدير · د.ع<input v-model="offer.retail" inputmode="decimal" required :disabled="vm.state.busy"></label><label class="inline-check"><input v-model="offer.active" type="checkbox" :disabled="vm.state.busy">مفعّلة للبيع</label></div></section><div class="formfoot"><button class="btn primary" :disabled="vm.state.busy">{{vm.state.busy?'جارٍ الحفظ…':'حفظ إعداد الربط'}}</button><button type="button" class="btn" :disabled="vm.state.busy" @click="draft=null;credential='';catalog=[]">إلغاء</button></div></form><TablePanel class="tablewrap"><table><thead><tr><th>الخدمة</th><th>الوكيل</th><th>الفئات</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="connection in vm.state.connections" :key="connection.id"><td>{{providerNames[connection.provider]}}</td><td>{{connection.account_name}}<small v-if="connection.company_balance!==undefined&&connection.gateway.balance_supported!==false">رصيد الشركة: {{connection.gateway.balance_supported===false?'مسار الرصيد غير وارد في توثيق الشركة':connection.company_balance===null?'لم يُجلب بعد':money(connection.company_balance)+' د.ع'}}</small><small v-if="connection.balance_updated_at">آخر جلب: {{time(connection.balance_updated_at)}} · رصيد وقت الجلب</small></td><td><button class="btn small" :aria-expanded="detailsId===connection.id" @click="detailsId=detailsId===connection.id?null:connection.id">عرض التفاصيل</button><RouterLink v-if="connection.provider==='topup'&&(canSetup||canAssign)" class="btn small" :to="canSetup?'/topup/allocation':'/topup/distribution'">{{canSetup?'تخصيص فئات Topup':'توزيع فئات Topup'}}</RouterLink><small v-if="connection.provider==='topup'&&connection.catalog_count!==undefined">{{connection.catalog_count===null?'لم يُستعلم عن الفئات بعد':connection.catalog_count===0?'الشركة رجّعت قائمة فئات فارغة':connection.catalog_count+' فئة من الشركة'}}</small><span v-else>{{connection.offers.length}}</span></td><td>{{!connection.active?'معطل':connection.provider==='topup'?(connection.credential_present?'التوكن محفوظ':'بانتظار التوكن'):connection.offers.some(row=>row.remote_id)?'مفعل':'بانتظار ربط الفئات'}}</td><td><div v-if="canSetup" class="actions"><button class="btn small" :disabled="vm.state.busy" @click="edit(connection)">تعديل</button><button class="btn small" :disabled="vm.state.busy" @click="toggle(connection)">{{connection.active?'تعطيل':'تفعيل'}}</button></div><button v-if="canSetup&&connection.provider==='topup'" class="btn small" :disabled="vm.state.busy||!connection.credential_present" @click="synchronize(connection,true)">جلب فئات الشركة</button><button v-if="connection.company_balance!==undefined&&connection.gateway.balance_supported!==false" class="btn small" :disabled="vm.state.busy||!connection.gateway.configured||connection.gateway.balance_supported===false" @click="refreshBalance(connection)">تحديث رصيد الشركة</button><button v-if="canAssign&&connection.provider!=='topup'&&connection.effective_offer_ids?.length" class="btn small" @click="assign(connection)">توزيع الفئات</button></td></tr></tbody></table></TablePanel><FinancePagination :meta="vm.state.connectionsMeta" :busy="vm.state.loading||vm.state.busy" @page="vm.load($event)"/><DigitalCategoryDetails v-if="details" :key="details.id" :connection="details" @close="detailsId=null"/><form v-if="assignment&&canAssign" class="digital-config" @submit.prevent="saveGrant"><div class="formgrid"><label>نوع التابع<select v-model="assignment.kind" @change="assignment.target='';assignment.offer_ids=[]"><option value="agent">وكيل فرعي</option><option value="pos">نقطة بيع</option></select></label><label>التابع<select v-model="assignment.target" required @change="loadAllocation"><option value="" disabled>اختر التابع</option><option v-for="row in assignmentTargets" :key="row.id" :value="row.id">{{row.name}}</option></select></label></div><h4>الفئات المسموحة</h4><div class="digital-checks"><label v-for="offer in assignmentOffers" :key="offer.id"><input v-model="assignment.offer_ids" type="checkbox" :value="offer.id">{{offer.name}}</label></div><label class="inline-check"><input v-model="assignment.active" type="checkbox">الخدمة مفعّلة</label><div class="formfoot"><button class="btn primary" :disabled="vm.state.busy||!assignment.target">حفظ الفئات</button><button type="button" class="btn" @click="assignment=null">إلغاء</button></div></form><TablePanel v-if="canAssign&&grants.length" class="tablewrap digital-grants"><table><thead><tr><th>الخدمة</th><th>التابع</th><th>الفئات</th><th>التفعيل</th></tr></thead><tbody><tr v-for="grant in grants" :key="grant.id"><td>{{providerNames[grant.connection.provider]}}</td><td>{{grant.target_name}}</td><td>{{grant.offer_ids.length}}</td><td><button class="digital-grant-switch" :class="{enabled:grant.active}" role="switch" :aria-checked="grant.active" :aria-label="`${providerNames[grant.connection.provider]} · ${grant.target_name}`" :disabled="vm.state.busy" @click="toggleGrant(grant)"><span class="digital-switch-track" aria-hidden="true"><span/></span><span>{{grant.active?'الخدمة مفعلة':'الخدمة معطلة'}}</span></button></td></tr></tbody></table></TablePanel><p v-if="!vm.state.connections.length" class="empty">لا توجد خدمات مربوطة</p></section></template>
